@@ -0,0 +1,68 @@
+import { createHmac, randomBytes } from "crypto";
+
+export interface SignedSessionToken {
+  sessionId: string;
+  userId: string;
+  issuedAt: number;
+  expiresAt: number;
+  signature: string;
+}
+
+const SIGNING_SECRET = process.env.SESSION_SIGNING_SECRET || generateSecret();
+const TOKEN_EXPIRY_MS = 7 * 24 * 60 * 60 * 1000; // 7 days
+
+function generateSecret(): string {
+  if (process.env.NODE_ENV === "production") {
+    throw new Error("SESSION_SIGNING_SECRET must be set in production");
+  }
+  return randomBytes(32).toString("hex");
+}
+
+export const signSession = (
+  sessionId: string,
+  userId: string,
+): SignedSessionToken => {
+  const issuedAt = Math.floor(Date.now() / 1000);
+  const expiresAt = issuedAt + Math.floor(TOKEN_EXPIRY_MS / 1000);
+
+  const payload = `${sessionId}.${userId}.${issuedAt}.${expiresAt}`;
+  const signature = createHmac("sha256", SIGNING_SECRET)
+    .update(payload)
+    .digest("hex");
+
+  return {
+    sessionId,
+    userId,
+    issuedAt,
+    expiresAt,
+    signature,
+  };
+};
+
+export const verifySignedToken = (
+  token: SignedSessionToken,
+): { valid: boolean; expired: boolean } => {
+  const payload = `${token.sessionId}.${token.userId}.${token.issuedAt}.${token.expiresAt}`;
+  const expectedSignature = createHmac("sha256", SIGNING_SECRET)
+    .update(payload)
+    .digest("hex");
+
+  if (token.signature !== expectedSignature) {
+    return { valid: false, expired: false };
+  }
+
+  const now = Math.floor(Date.now() / 1000);
+  if (now > token.expiresAt) {
+    return { valid: false, expired: true };
+  }
+
+  return { valid: true, expired: false };
+};
+
+export const encodeToken = (token: SignedSessionToken): string => {
+  return Buffer.from(JSON.stringify(token)).toString("base64url");
+};
+
+export const decodeToken = (encoded: string): SignedSessionToken => {
+  return JSON.parse(Buffer.from(encoded, "base64url").toString("utf-8"));
+};
